//------------------------------------------------------------------------------
//Callback Name: apply_cb
//------------------------------------------------------------------------------
int SouDonZuanBanJin::apply_cb()
{
    int errorCode = 0;
    try
    {
        RefreshNxContext();
        UfSessionGuard ufSession;
        if (Body1 == NULL || feature3 == NULL)
        {
            throw std::runtime_error("请先选择一个钣金面并生成展开数据。");
        }

        bool TheConCuan = GetToggleValue(ConCuan);
        bool TheJiGuan = GetToggleValue(JiGuan);
        bool TheZeWan = GetToggleValue(ZeWan);
        bool TheHanJie = GetToggleValue(HanJie);

        if (!UpdateBodyZThicknessAttribute(workPart->Features()->SheetmetalManager(), Body1, &unfoldThickness) &&
            !unfoldThickness.empty())
        {
            Body1->SetUserAttribute("Z", -1, unfoldThickness.c_str(), Update::OptionNow);
        }

        if (TheConCuan == true)
        {
            Body1->SetUserAttribute("冲床", -1, "Y", Update::OptionNow);
        }
        else
        {
            Body1->SetUserAttribute("冲床", -1, "", Update::OptionNow);
        }


        //设置激光属性

        if (TheJiGuan == true)
        {
            Body1->SetUserAttribute("激光", -1, "Y", Update::OptionNow);
        }
        else
        {
            Body1->SetUserAttribute("激光", -1, "", Update::OptionNow);
        }

        //设置折弯属性

        if (TheZeWan == true)
        {
            Body1->SetUserAttribute("折弯", -1, "Y", Update::OptionNow);
        }
        else
        {
            Body1->SetUserAttribute("折弯", -1, "", Update::OptionNow);
        }


        //设置焊接属性

        if (TheHanJie == true)
        {
            Body1->SetUserAttribute("焊接", -1, "Y", Update::OptionNow);
        }
        else
        {
            Body1->SetUserAttribute("焊接", -1, "", Update::OptionNow);
        }

        int Body1ID = 0;
        //Body1->GetReferenceAttribute("BodyID");

        char ExName1Y[256];
        char ExName1YY[256];
        char ExName1[256];
        char ExName1X[256];
        char ExName1XX[256];
        char ExName2[256];
        char SuLian[256];
        char ZSuLian[256];
        
        if (Body1->HasUserAttribute("BodyID", NXObject::AttributeType::AttributeTypeInteger, -1))
        {
            Body1ID = Body1->GetIntegerAttribute("BodyID");

            sprintf(ExName1Y, "Y_%d", Body1ID);
            sprintf(ExName1YY, "YY_%d", Body1ID);
            sprintf(ExName1X, "X_%d", Body1ID);
            sprintf(ExName1XX, "XX_%d", Body1ID);
            sprintf(SuLian, "SuLian_%d", Body1ID);
            sprintf(ZSuLian, "ZSuLian_%d", Body1ID);

        }

            srand(static_cast<unsigned int>(time(0)));
            Body1ID = (rand() % 9001) + 999;//生成4位随机数
            Body1->SetUserAttribute("BodyID", -1, Body1ID, Update::Option::OptionNow);
        NXOpen::Expression* expression1Y;
        NXOpen::Expression* expression1YY;
        NXOpen::Expression* expression1X;
        NXOpen::Expression* expression1XX;
        NXOpen::Expression* expsuLian;
        NXOpen::Expression* expZsuLian;
        NXOpen::Unit* nullNXOpen_Unit(NULL);

        sprintf(ExName1Y, "Y_%d", Body1ID);
        sprintf(ExName1YY, "YY_%d", Body1ID);
        sprintf(ExName1X, "X_%d", Body1ID);
        sprintf(ExName1XX, "XX_%d", Body1ID);
        sprintf(SuLian, "SuLian_%d", Body1ID);

        expression1Y = workPart->Expressions()->GetAttributeExpression(feature3, "Minimum Y", NXOpen::NXObject::AttributeTypeReal, -1);

        sprintf(ExName1, "YY_%d=ROUND(%s)", Body1ID, ExName1Y);
        expression1Y->SetName(ExName1Y);
        expression1YY = workPart->Expressions()->CreateExpressionWithUnit("Integer", ExName1, nullNXOpen_Unit);

        expression1X = workPart->Expressions()->GetAttributeExpression(feature3, "Minimum X", NXOpen::NXObject::AttributeTypeReal, -1);
        sprintf(ExName2, "XX_%d=ROUND(%s)", Body1ID, ExName1X);
        expression1X->SetName(ExName1X);
        expression1XX = workPart->Expressions()->CreateExpressionWithUnit("Integer", ExName2, nullNXOpen_Unit);
        expsuLian = workPart->Expressions()->GetAttributeExpression(Body1, "sulian", NXOpen::NXObject::AttributeTypeInteger, -1);

        expsuLian->SetName(SuLian);
        sprintf(ZSuLian, "ZSuLian_%d=数量*%s", Body1ID, SuLian);
        expZsuLian = workPart->Expressions()->CreateExpressionWithUnit("Integer", ZSuLian, nullNXOpen_Unit);

    }
    catch(exception& ex)
    {
        //---- Enter your exception handling code here -----
        errorCode = 1;
        SouDonZuanBanJin::theUI->NXMessageBox()->Show("Block Styler", NXOpen::NXMessageBox::DialogTypeError, ex.what());
    }
    return errorCode;
}

//------------------------------------------------------------------------------
//Callback Name: filter_cb
//------------------------------------------------------------------------------
int SouDonZuanBanJin::filter_cb(NXOpen::BlockStyler::UIBlock* block, NXOpen::TaggedObject* selectedObject)
{
    try
    {
        if (block != selectionEdge0)
        {
            return UF_UI_SEL_ACCEPT;
        }

        if (!directionEdgeRequired)
        {
            return UF_UI_SEL_REJECT;
        }

        if (facetag == NULL_TAG || selectedObject == NULL)
        {
            return UF_UI_SEL_REJECT;
        }

        NXOpen::Edge* selectedEdge(dynamic_cast<NXOpen::Edge*>(selectedObject));
        NXOpen::Face* selectedFace(dynamic_cast<NXOpen::Face*>(NXOpen::NXObjectManager::Get(facetag)));
        return IsStraightEdge(selectedEdge) && IsEdgeOnFace(selectedEdge, selectedFace) ? UF_UI_SEL_ACCEPT : UF_UI_SEL_REJECT;
    }
    catch (...)
    {
        return UF_UI_SEL_REJECT;
    }
}

//------------------------------------------------------------------------------
//Callback Name: update_cb
//------------------------------------------------------------------------------
int SouDonZuanBanJin::update_cb(NXOpen::BlockStyler::UIBlock* block)
{
    try
    {

        if(block == selection0)
        {
            RefreshNxContext();
            UfSessionGuard ufSession;

            PropertyList* selection0Props = selection0->GetProperties();
            std::vector<NXOpen::TaggedObject*> face = selection0Props->GetTaggedObjectVector("SelectedObjects");
            delete selection0Props;
            selection0Props = NULL;

            if (face.empty())
            {
                facetag = NULL_TAG;
                bodytag = NULL_TAG;
                Body1 = NULL;
                feature1 = NULL;
                feature3 = NULL;
                directionEdgeRequired = false;
                return 0;
            }

            facetag = face[0]->Tag();
            UF_MODL_ask_face_body(facetag, &bodytag);

            Body1 = (dynamic_cast<NXOpen::Body*>(NXOpen::NXObjectManager::Get(bodytag)));
            NXOpen::Face* face2(dynamic_cast<NXOpen::Face*>(face[0]));//强制转换为NX对象
            feature3 = NULL;
            directionEdgeRequired = false;
            if (Body1 == NULL || face2 == NULL)
            {
                throw std::runtime_error("请选择有效的实体面。");
            }

            NXOpen::Face* markedBaseFace = FindMarkedAdjacentLargestPlanarFace(Body1);
            if (markedBaseFace != NULL)
            {
                face2 = markedBaseFace;
                facetag = face2->Tag();
            }

            if (Body1->HasUserAttribute("数量",NXObject::AttributeType::AttributeTypeInteger,-1)==false)
            {
                Body1->SetUserAttribute("数量", -1, intVal[2], Update::OptionNow);
            }

            int layer1=Body1->Layer();
            if (layer1==1)
            {
                std::vector<NXOpen::DisplayableObject*> objectArray1(1);
                objectArray1[0] = Body1;
                workPart->Layers()->MoveDisplayableObjects(10, objectArray1);
            }
            const SheetmetalDialogOptions sheetmetalOptions = CollectSheetmetalDialogOptions(
                reliefDepthDouble,
                reliefWidthDouble,
                innerRadiusDouble);
            ApplySheetmetalPreferencesBeforeConvert(workPart, sheetmetalOptions);

            //实体转换钣金
           
           // workPart->Preferences()->PartSheetmetal()->SetBendRadius(false, "0.2");

            NXOpen::Features::Feature* nullNXOpen_Features_Feature(NULL);
            NXOpen::Features::SheetMetal::ConvertToSheetmetalBuilder* convertToSheetmetalBuilder1;
            convertToSheetmetalBuilder1 = workPart->Features()->SheetmetalManager()->CreateConvertToSheetmetalFeatureBuilder(nullNXOpen_Features_Feature);
            convertToSheetmetalBuilder1->SetApplicationContext(NXOpen::Features::SheetMetal::ApplicationContextNxSheetMetal);
            convertToSheetmetalBuilder1->SetBendReliefType(NXOpen::Features::SheetMetal::ConvertToSheetmetalBuilder::BendReliefTypeOptionsSquare);
            NXOpen::Expression* expression1;
            expression1 = convertToSheetmetalBuilder1->BendReliefDepth();
            expression1->SetRightHandSide(FormatDouble(sheetmetalOptions.reliefDepth, 6));
            NXOpen::Expression* expression2;
            expression2 = convertToSheetmetalBuilder1->BendReliefWidth();
            expression2->SetRightHandSide(FormatDouble(sheetmetalOptions.reliefWidth, 6));
            convertToSheetmetalBuilder1->SetMaintainZeroBendRadius(sheetmetalOptions.innerRadius <= 0.0);
            NXOpen::Face* nullNXOpen_Face(NULL);
            convertToSheetmetalBuilder1->SetBaseFace(nullNXOpen_Face);
            convertToSheetmetalBuilder1->SetBaseFace(face2);
            feature1 = convertToSheetmetalBuilder1->CommitFeature();
            convertToSheetmetalBuilder1->Destroy();
            theSession->CleanUpFacetedFacesAndEdges();
            Body1 = ResolveFeatureBody(feature1, Body1);
            RuleConfig ruleConfig = LoadRuleConfig();
            ApplyNeutralFactorByRules(workPart, workPart->Features()->SheetmetalManager(), Body1, ruleConfig);
            
            UpdateBodyZThicknessAttribute(workPart->Features()->SheetmetalManager(), Body1, &unfoldThickness);

             if (GetToggleValue(togglebaobian))
             {
                 baobian();
             }

             directionEdgeRequired = BodyHasStraightEdge(Body1);
             if (!directionEdgeRequired)
             {
                 feature3 = CreateDefaultFlatPattern(face2);
                 UpdateBodyFlatPatternSizeAttribute(Body1, feature3);
             }
        }

        else if(block == selectionEdge0)
        {
            RefreshNxContext();
            UfSessionGuard ufSession;
            if (!directionEdgeRequired)
            {
                return 0;
            }

            if (facetag == NULL_TAG || Body1 == NULL || feature1 == NULL)
            {
                throw std::runtime_error("请先选择展开基面。");
            }

            NXOpen::Face* face1(dynamic_cast<NXOpen::Face*>(NXOpen::NXObjectManager::Get(facetag)));
            if (face1 == NULL)
            {
                throw std::runtime_error("请重新选择展开基面。");
            }

            PropertyList* selectionEdge0Props = selectionEdge0->GetProperties();
            std::vector<NXOpen::TaggedObject*> edges = selectionEdge0Props->GetTaggedObjectVector("SelectedObjects");
            delete selectionEdge0Props;
            selectionEdge0Props = NULL;
            if (edges.empty())
            {
                if (feature3 != NULL)
                {
                    return 0;
                }
                throw std::runtime_error("请选择展开 X 方向边。");
            }

            NXOpen::Edge* xAxisEdge(dynamic_cast<NXOpen::Edge*>(edges[0]));
            if (xAxisEdge == NULL)
            {
                throw std::runtime_error("请选择有效的展开 X 方向边。");
            }
            if (!IsStraightEdge(xAxisEdge))
            {
                throw std::runtime_error("请选择直线边作为展开 X 方向边。");
            }
            if (!IsEdgeOnFace(xAxisEdge, face1))
            {
                throw std::runtime_error("方向边必须是所选展开基面的边。");
            }

            NXOpen::Point3d startPoint;
            NXOpen::Point3d endPoint;
            xAxisEdge->GetVertices(&startPoint, &endPoint);

            NXOpen::Features::Feature* nullNXOpen_Features_Feature(NULL);
            NXOpen::Features::SheetMetal::FlatPatternBuilder* flatPatternBuilder1;
            flatPatternBuilder1 = workPart->Features()->SheetmetalManager()->CreateFlatPatternBuilder(nullNXOpen_Features_Feature);
            flatPatternBuilder1->SetApplicationContext(NXOpen::Features::SheetMetal::ApplicationContextNxSheetMetal);
            flatPatternBuilder1->SetOrientation(NXOpen::Features::SheetMetal::FlatSolidBuilder::OrientationTypeEdge);
            flatPatternBuilder1->OuterCornerTreatment()->SetTreatmentType(NXOpen::Features::SheetMetal::CornerTreatmentBuilder::CornerTreatmentTypeRadius);
            flatPatternBuilder1->OuterCornerTreatment()->Value()->SetFormula("1");
            flatPatternBuilder1->UpwardFace()->SetValue(face1);
            flatPatternBuilder1->XAxisEdge()->SetValue(xAxisEdge);
            flatPatternBuilder1->SetReferenceVertex(endPoint);

            feature3 = flatPatternBuilder1->CommitFeature();
            flatPatternBuilder1->Destroy();
            theSession->CleanUpFacetedFacesAndEdges();
            UpdateBodyFlatPatternSizeAttribute(Body1, feature3);

        }

        else if (block == togglebaobian)
        {


            if (GetToggleValue(togglebaobian))
            {
                if (facetag != NULL_TAG)
                {
                    baobian();
                }
            }
            else
            {

                if (objects1a.size() > 0)
                {
                    NXOpen::Session::UndoMarkId markId1;
                    markId1 = theSession->SetUndoMark(NXOpen::Session::MarkVisibilityInvisible, "Delete");
                    theSession->UpdateManager()->ClearErrorList();

                    int nErrs1;
                    nErrs1 = theSession->UpdateManager()->AddObjectsToDeleteList(objects1a);

                    NXOpen::Session::UndoMarkId id1;
                    id1 = theSession->NewestVisibleUndoMark();

                    int nErrs2;
                    nErrs2 = theSession->UpdateManager()->DoUpdate(id1);

                    theSession->DeleteUndoMark(markId1, NULL);

                }
            }
        }
        else if(block == ConCuan)
        {
        //---------Enter your code here-----------
        }
        else if(block == JiGuan)
        {
        //---------Enter your code here-----------
        }
        else if(block == ZeWan)
        {
        //---------Enter your code here-----------
        }
        else if(block == HanJie)
        {
        //---------Enter your code here-----------
        }
        else if (block == settingsButton)
        {
            LaunchBendFactorSettings();
        }
    }
    catch(exception& ex)
    {
        //---- Enter your exception handling code here -----
        SouDonZuanBanJin::theUI->NXMessageBox()->Show("Block Styler", NXOpen::NXMessageBox::DialogTypeError, ex.what());
    }
    return 0;
}

